def countFillings(s):
    MOD = 10**9 + 7
    n = len(s)
    if n % 2:
        return 0
    half = n // 2
    dp = [0] * (half + 2)     # dp[b] = ways with balance b
    dp[0] = 1
    for i, ch in enumerate(s):
        new = [0] * (half + 2)
        top = min(i, half)
        for b in range(top + 1):
            v = dp[b]
            if not v:
                continue
            if ch != ')' and b + 1 <= half:
                new[b + 1] = (new[b + 1] + v) % MOD
            if ch != '(' and b > 0:
                new[b - 1] = (new[b - 1] + v) % MOD
        dp = new
    return dp[0]
